#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";

const ROOT = path.resolve(import.meta.dirname, "..");
const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8"));
let commit = "unknown";
try {
  commit = execSync("git rev-parse --short HEAD", { cwd: ROOT, encoding: "utf8" }).trim();
} catch { /* shallow */ }

const out = `// @ts-check
/** Generated by scripts/write-build-info.mjs — do not edit by hand. */
export const GAME_NAME = "More Ducks!";
export const GAME_VERSION = ${JSON.stringify(pkg.version)};
export const GAME_TAGLINE = ${JSON.stringify(pkg.description)};
export const BUILD_COMMIT = ${JSON.stringify(commit)};
`;

fs.writeFileSync(path.join(ROOT, "src/data/build-info.js"), out);
console.log("build-info", commit);
